# Extract the home team scores for matches where Melbourne is the home team
melbourne_home = df[df['home team'] == 'melbourne'].copy()

# Parse the home team score column to get the numeric score (the part inside parentheses)
def extract_score(score_str):
    import re
    match = re.search(r'\((\d+)\)', score_str)
    if match:
        return int(match.group(1))
    else:
        parts = score_str.split()
        for part in parts:
            if part.startswith('(') and part.endswith(')'):
                return int(part[1:-1])
        return None

melbourne_home['home_score_numeric'] = melbourne_home['home team score'].apply(extract_score)

# Get all home team scores across the dataframe
all_home_scores = df['home team score'].apply(extract_score)

# Find the unique sorted home scores
unique_sorted_scores = sorted(all_home_scores.unique())

# Check if there are at least two distinct scores
if len(unique_sorted_scores) >= 2:
    second_lowest = unique_sorted_scores[1]
    # Check if Melbourne's home score is equal to the second lowest score
    melbourne_scores = melbourne_home['home_score_numeric'].tolist()
